message:
Translate the following Rust struct to idiomatic Rust. Try to avoid using raw pointers in the translation of the struct.
If the struct is designed as a cloneable struct, try to add/implement the `Clone` trait for the struct.
```rust
use libc::{size_t, uint32_t, uint64_t};
pub type __uint32_t = libc::c_uint;
pub type __uint64_t = libc::c_ulong;
pub type uint32_t = __uint32_t;
pub type uint64_t = __uint64_t;
#[derive(Copy, Clone, Debug)]
#[repr(C)]
pub struct md5_ctx {
    pub state: [uint32_t; 4],
    pub bit_len: uint64_t,
    pub buffer: [libc::c_uchar; 64],
    pub buffer_len: size_t,
}

```

Output the translated struct into this format (wrap with the following tags):
----STRUCT----
```rust
// Your translated struct here
```
----END STRUCT----

Also output a minimal JSON spec that maps the unidiomatic Rust layout to the idiomatic Rust struct.
If you rename the idiomatic type, set the `i_type` field accordingly (still set it even if unchanged).

Naming guardrails (do not skip):
- The repr(C) type must stay exactly `Cmd5_ctx` (same casing as the original C identifier). Never CamelCase or otherwise rename the C-side type.
- Do not re-declare the repr(C) struct; assume `pub struct Cmd5_ctx` already exists in the compiled crate and only reference it.
- Do not emit conversion functions nor reference the repr(C) alias (e.g. `Cmd5_ctx`) directly; keep the output strictly to the idiomatic Rust type and any pure-Rust helper methods. The verifier will synthesize the bridging code.
- If you rename the idiomatic type, the converters must be emitted exactly as `unsafe fn Cmd5_ctx_to_<idiomatic_name>_mut(...)` and `unsafe fn <idiomatic_name>_to_Cmd5_ctx_mut(...)`.
- When the C layout uses typedefs such as `uint32_t` or `uint8_t`, either import them from `libc` or map them to the corresponding Rust primitives (e.g. `u32`, `u8`). The generated code must compile without missing typedefs.
Full JSON Schema for the SPEC (do not output the schema; output only an instance that conforms to it):
```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "sactor://spec.schema.json",
  "title": "Sactor Idiomatic Translation Spec",
  "description": "Schema describing mappings between unidiomatic (repr(C)) Rust and idiomatic Rust for structs and function arguments.",
  "$defs": {
    "PtrShape": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "ptr": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "kind": { "enum": ["slice", "cstring", "ref"] },
            "len_from": { "type": "string", "description": "Name of the unidiomatic length field." },
            "len_const": { "type": "integer", "minimum": 0, "description": "Constant element count for the pointer." },
            "null": { "enum": ["nullable", "forbidden"], "description": "Whether the pointer can be NULL." }
          },
          "required": ["kind"]
        }
      },
      "required": ["ptr"]
    },
    "UField": {
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "name": { "type": "string" },
        "type": { "type": "string" },
        "shape": {
          "oneOf": [
            { "const": "scalar", "description": "Scalar value (integer, float, bool, char, or any non-pointer data structures)" },
            { "$ref": "#/$defs/PtrShape", "description": "Pointer type (raw pointer, slice, or C string)" }
          ]
        }
      },
      "required": ["name", "shape"]
    },
    "IField": {
      "type": "object",
      "description": "Idiomatic-side field path. Special convention: if name == 'ret', this Field describes the function return mapping.",
      "additionalProperties": true,
      "properties": {
        "name": { "type": "string", "description": "Idiomatic field path or 'ret' for function return." },
        "type": { "type": "string" }
      },
      "required": ["name"]
    },
    "EnumDiscriminant": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "tag": { "type": "string", "description": "u_field.name of the discriminant/tag" },
        "equals": { "type": ["integer", "string"], "description": "Value of tag that selects this variant" }
      },
      "required": ["tag", "equals"]
    },
    "EnumVariant": {
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "name": { "type": "string", "description": "Idiomatic enum variant name" },
        "when": { "$ref": "#/$defs/EnumDiscriminant" },
        "payload": { "type": "array", "items": { "$ref": "#/$defs/Field" } }
      },
      "required": ["name", "when"]
    },
    "Field": {
      "type": "object",
      "description": "Field mapping between unidiomatic C-style field and idiomatic Rust path.",
      "properties": {
        "u_field": { "$ref": "#/$defs/UField" },
        "i_field": { "$ref": "#/$defs/IField" },
        "ownership": { "type": "string", "enum": ["owning", "transient"], "description": "Optional ownership hint." },
        "compare": {
          "type": "string",
          "enum": ["by_value", "by_slice", "skip"],
          "description": "Comparison strategy for roundtrip tests. Use 'skip' generously for values that may legitimately diverge (raw pointers, aliasing views, externally-owned buffers, handles, allocator state, etc.) so the automated selftest stays permissive."
        },
        "llm_note": { "type": "string", "description": "Free-form note for LLM when automatic codegen is insufficient (e.g., aliasing/offset semantics)." }
      },
      "required": ["u_field", "i_field"]
    },
    "StructSpec": {
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "version": { "type": "string" },
        "struct_name": { "type": "string", "description": "Name of the translated idiomatic struct." },
        "fields": { "type": "array", "items": { "$ref": "#/$defs/Field" }, "minItems": 1 },
        "i_kind": { "type": "string", "enum": ["struct", "enum"], "default": "struct" },
        "i_type": { "type": "string", "description": "Idiomatic type name (useful when i_kind=enum)" },
        "variants": { "type": "array", "items": { "$ref": "#/$defs/EnumVariant" } }
      },
      "required": ["fields", "i_kind", "i_type"]
    },
    "FunctionSpec": {
      "type": "object",
      "description": "Function argument/return mapping. Return values are expressed via a Field whose i_field.name == 'ret'.",
      "additionalProperties": true,
      "properties": {
        "version": { "type": "string" },
        "function_name": { "type": "string", "description": "Name of the translated idiomatic function." },
        "fields": { "type": "array", "items": { "$ref": "#/$defs/Field" }, "minItems": 1 }
      },
      "required": ["fields"]
    }
  },
  "oneOf": [
    { "$ref": "#/$defs/StructSpec" },
    { "$ref": "#/$defs/FunctionSpec" }
  ]
}

